import{_ as s,C as r,o as d,c as e,j as i,a as l,E as t,a2 as o}from"./chunks/framework.C21TwvGF.js";const K=JSON.parse('{"title":"2-dars (Mentor). 2-dars: Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD) tamoyillari va bosqichlari","description":"","frontmatter":{"title":"2-dars (Mentor). 2-dars: Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD) tamoyillari va bosqichlari","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"10-sinf (UX/UI)","link":"/mentor/10-sinf-uxui/"},"week":{"n":1,"link":"/mentor/10-sinf-uxui/hafta-01/"},"g":2,"title":"2-dars: Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD) tamoyillari va bosqichlari","lead":"Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD)","slide":"/slaydlar/10-sinf-uxui/hafta-01/dars-2.html","test":"/slaydlar/10-sinf-uxui/hafta-01/dars-2-test.html","student_link":"/10-sinf-uxui/hafta-01/dars-2","tabs":[{"g":1,"link":"/mentor/10-sinf-uxui/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/10-sinf-uxui/hafta-01/dars-2","current":true},{"g":3,"link":"/mentor/10-sinf-uxui/hafta-01/dars-3","current":false}],"prev":{"g":1,"title":"1-dars: UX dizaynning strategik roli va biznes maqsadlari bilan uyg‘unlashuvi","link":"/mentor/10-sinf-uxui/hafta-01/dars-1"},"next":{"g":3,"title":"3-dars: Interfeys dizaynida asosiy tamoyillar: Usability, Accessibility, Simplicity","link":"/mentor/10-sinf-uxui/hafta-01/dars-3"}}},"headers":[],"relativePath":"mentor/10-sinf-uxui/hafta-01/dars-2.md","filePath":"mentor/10-sinf-uxui/hafta-01/dars-2.md"}'),h={name:"mentor/10-sinf-uxui/hafta-01/dars-2.md"},u={class:"blk"},m={id:"darsning-maqsadi",tabindex:"-1"},g={class:"blk"},y={id:"kutilayotgan-natijalar-o-quvchi-bilishi-kerak",tabindex:"-1"},k={class:"blk"},q={id:"kerakli-jihozlar-va-vositalar",tabindex:"-1"},b={class:"blk"},v={id:"dars-rejasi-80-daqiqa",tabindex:"-1"},c={class:"blk"},p={id:"nazariy-ma-lumotlar",tabindex:"-1"},f={class:"blk"},z={id:"amaliy-mashg-ulot-va-topshiriqlar",tabindex:"-1"},x={class:"blk"},D={id:"tezkor-nazorat-savollari",tabindex:"-1"},C={class:"blk"},U={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function _(T,a,j,F,P,I){const n=r("Icon");return d(),e("div",null,[a[27]||(a[27]=i("p",null,[i("strong",null,"Fan:"),l(" Advanced UX/UI dizayn va Advanced Front-end"),i("br"),i("strong",null,"Sinf:"),l(" 10-sinf"),i("br"),i("strong",null,"Hafta:"),l(" 1-hafta, 2-dars (umumiy 2-dars)"),i("br"),i("strong",null,"Dars davomiyligi:"),l(" 80 daqiqa")],-1)),a[28]||(a[28]=i("hr",null,null,-1)),i("div",u,[i("h2",m,[t(n,{name:"file-text"}),a[0]||(a[0]=l(" Darsning maqsadi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#darsning-maqsadi","aria-label":'Permalink to "<Icon name="file-text" /> Darsning maqsadi"'},"​",-1))]),a[2]||(a[2]=i("p",null,"O'quvchilarga Foydalanuvchiga yo'naltirilgan dizayn (User-Centered Design — UCD / FYD) falsafasi, uning kelib chiqish tarixi (Donald Norman, 1993) va zamonaviy raqamli mahsulotlar yaratishdagi ahamiyatini o'rgatish; UCD ning 10 ta asosiy tamoyili (izchillik, sodda til, kuch sarfini kamaytirish, feedback, xatolarning oldini olish va boshqalar) hamda 4 bosqichli iterativ siklini (kontekst, talablar, yechim, baholash) amaliy misollarda tahlil qilish ko'nikmalarini shakllantirish.",-1)),a[3]||(a[3]=i("hr",null,null,-1))]),i("div",g,[i("h2",y,[t(n,{name:"file-text"}),a[4]||(a[4]=l(" Kutilayotgan natijalar (O'quvchi bilishi kerak) ",-1)),a[5]||(a[5]=i("a",{class:"header-anchor",href:"#kutilayotgan-natijalar-o-quvchi-bilishi-kerak","aria-label":`Permalink to "<Icon name="file-text" /> Kutilayotgan natijalar (O'quvchi bilishi kerak)"`},"​",-1))]),a[6]||(a[6]=i("ul",null,[i("li",null,"UCD (User-Centered Design) tushunchasi va uning iterativ tabiatini aniq tushunish;"),i("li",null,"Donald Normanning UX sohasiga qo'shgan hissasini bilish;"),i("li",null,"UCD ning 10 ta asosiy tamoyilini amaliy loyihalarda farqlay olish;"),i("li",null,"IT startaplarning muvaffaqiyatsizlikka uchrashida UCD ning yo'qligi qanday rol o'ynashini (17% startaplar xatosi) statistik tushunish;"),i("li",null,"4 bosqichli UCD rivojlanish sikli (Kontekst -> Talablar -> Yechim -> Baholash) bo'yicha mustaqil loyiha xaritasini tuza olish.")],-1)),a[7]||(a[7]=i("hr",null,null,-1))]),i("div",k,[i("h2",q,[t(n,{name:"file-text"}),a[8]||(a[8]=l(" Kerakli jihozlar va vositalar ",-1)),a[9]||(a[9]=i("a",{class:"header-anchor",href:"#kerakli-jihozlar-va-vositalar","aria-label":'Permalink to "<Icon name="file-text" /> Kerakli jihozlar va vositalar"'},"​",-1))]),a[10]||(a[10]=i("ul",null,[i("li",null,"Kompyuter yoki noutbuk;"),i("li",null,"Veb-brauzer, Figma yoki FigJam doskasi;"),i("li",null,"Proyektor yoki monitor (namoyish uchun);"),i("li",null,"Qog'oz, stikerlar va qalamlar (prototiplash mashqi uchun).")],-1)),a[11]||(a[11]=i("hr",null,null,-1))]),i("div",b,[i("h2",v,[t(n,{name:"file-text"}),a[12]||(a[12]=l(" Dars rejasi (80 daqiqa) ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi (80 daqiqa)"'},"​",-1))]),a[14]||(a[14]=o('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Tavsif</th></tr></thead><tbody><tr><td><strong>00–10 min</strong></td><td>O&#39;tgan mavzuni takrorlash</td><td>UX ning biznesdagi strategik roli, konversiya va metrikalar bo&#39;yicha savol-javob</td></tr><tr><td><strong>10–25 min</strong></td><td>Yangi mavzu: UCD nima va uning tarixi</td><td>UCD ta&#39;rifi, Donald Norman (1993, Apple), UCD ning asosiy elementlari</td></tr><tr><td><strong>25–40 min</strong></td><td>UCD ning 10 ta fundamental tamoyili</td><td>Moslik, sodda til, minimal harakat, qayta aloqa (feedback), xatolarni oldini olish</td></tr><tr><td><strong>40–55 min</strong></td><td>UCD ning 4 bosqichli iterativ sikli</td><td>Kontekstni aniqlash -&gt; Talablar -&gt; Loyihalash -&gt; Haqiqiy foydalanuvchilar bilan baholash</td></tr><tr><td><strong>55–75 min</strong></td><td>Amaliy mashg&#39;ulot</td><td>Talabalar jamoasida mavjud mobil ilovani UCD tamoyillari bo&#39;yicha audit qilish</td></tr><tr><td><strong>75–80 min</strong></td><td>Xulosa va darsni yakunlash</td><td>Asosiy xulosalarni mustahkamlash, tezkor savollar</td></tr></tbody></table><hr>',2))]),i("div",c,[i("h2",p,[t(n,{name:"file-text"}),a[15]||(a[15]=l(" Nazariy ma'lumotlar ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#nazariy-ma-lumotlar","aria-label":`Permalink to "<Icon name="file-text" /> Nazariy ma'lumotlar"`},"​",-1))]),a[17]||(a[17]=o(`<h3 id="_1-foydalanuvchiga-yo-naltirilgan-dizayn-ucd-nima" tabindex="-1">1. Foydalanuvchiga yo‘naltirilgan dizayn (UCD) nima? <a class="header-anchor" href="#_1-foydalanuvchiga-yo-naltirilgan-dizayn-ucd-nima" aria-label="Permalink to &quot;1. Foydalanuvchiga yo‘naltirilgan dizayn (UCD) nima?&quot;">​</a></h3><p><strong>Foydalanuvchiga yo‘naltirilgan dizayn (UCD – User-Centered Design / FYD):</strong> Mahsulotni loyihalash va ishlab chiqishda foydalanuvchini jarayonning markaziga qo‘yishga qaratilgan jarayonlar majmuidir. Ya&#39;ni, mahsulot dasturchi yoki dizaynerning shaxsiy didi asosida emas, balki real foydalanuvchilarning talablari, maqsadlari va fikr-mulohazalarini hisobga olgan holda yaratiladi.</p><p><strong>Tarix:</strong> 1993-yilda Apple kompaniyasi xodimi <strong>Donald Norman</strong> o‘z lavozimiga dunyoda birinchi bo‘lib &quot;User Experience Architect&quot; (Foydalanuvchi tajribasi me&#39;mori) iborasini kiritgan. U tizimlar foydalanuvchi tajribasining barcha jihatlarini (qutini ochishdan tortib dasturdan foydalanishgacha) hisobga olgan holda loyihalashtirilishi kerakligini ta&#39;kidlagan.</p><p><strong>UCD ning 4 ta asosiy elementi:</strong></p><ol><li><strong>Ko‘rinarlilik (Visibility):</strong> Foydalanuvchi mahsulotni ko&#39;rgan ilk soniyalardanoq uning nima ekanini, qanday ishlashini va nimalar qila olishini anglay olishi kerak.</li><li><strong>Kirish imkoniyati (Accessibility):</strong> Ma&#39;lumotlarni tez va oson topish vositalari (qidiruv, navigatsiya, menyu).</li><li><strong>O‘qish osonligi (Readability):</strong> Kontrast, shrift o&#39;lchamlari va tartibli kompozitsiya.</li><li><strong>Tilning soddaligi (Plain Language):</strong> Murakkab texnik jargonlarsiz, qisqa va ravon tushuntirish.</li></ol><h3 id="_2-ucd-ning-10-ta-asosiy-tamoyili" tabindex="-1">2. UCD ning 10 ta asosiy tamoyili <a class="header-anchor" href="#_2-ucd-ning-10-ta-asosiy-tamoyili" aria-label="Permalink to &quot;2. UCD ning 10 ta asosiy tamoyili&quot;">​</a></h3><p>Rasmiy o&#39;quv qo&#39;llanmasiga muvofiq, UCD ning asosiy tamoyillari quyidagilardir:</p><ol><li><strong>Foydalanuvchi ehtiyojlariga mos noyob dizayn yaratish:</strong> Maqsadli auditoriyaning yoshi, muhiti va qurilmasini inobatga olish.</li><li><strong>Moslik va izchillik (Consistency):</strong> Butun mahsulot bo&#39;ylab bir xil uslub, tugma shakllari va navigatsiya qoidalariga amal qilish.</li><li><strong>Tushunarli va sodda til:</strong> Texnik xatolik kodlari o&#39;rniga insoniy tushunarli matnlardan foydalanish (masalan, &quot;Error 404&quot; o&#39;rniga &quot;Kechirasiz, sahifa topilmadi&quot;).</li><li><strong>Foydalanuvchi kuch sarfini kamaytirish (Minimize Effort):</strong> Bajarilishi kerak bo&#39;lgan kliklar va harakatlar sonini minimal darajaga tushirish.</li><li><strong>Oson topiladigan ko‘rsatmalar:</strong> Foydalanuvchiga yordamchi matnlar (tooltips, placeholder) taqdim etish.</li><li><strong>Qayta aloqa (Feedback):</strong> Tizim har bir harakatga darhol javob qaytarishi shart (masalan, yuklanish indikatori, tugmaning bosilish animatsiyasi).</li><li><strong>Navigatsiyani soddalashtirish:</strong> &quot;Orqaga&quot;, &quot;Bekor qilish&quot; (Undo) va qidiruv vositalari doim ko&#39;z oldida bo&#39;lishi.</li><li><strong>Harakat erkinligi (User Control &amp; Freedom):</strong> Foydalanuvchiga adashib bosilgan amalni to&#39;xtatish yoki orqaga qaytarish imkoniyatini berish.</li><li><strong>Aniq ma&#39;lumot (Clarity):</strong> Ekranni ortiqcha ikkinchi darajali ma&#39;lumotlar bilan to&#39;ldirmaslik, bo&#39;sh joylardan (white space) oqilona foydalanish.</li><li><strong>Xatolarning oldini olish (Error Prevention):</strong> Xato yuz berishiga yo&#39;l qo&#39;ymaslik (masalan, sana tanlashda kalendardan foydalanish, tasdiqlash oynalari).</li></ol><h3 id="_3-ucd-ning-biznesdagi-statistik-afzalliklari" tabindex="-1">3. UCD ning biznesdagi statistik afzalliklari <a class="header-anchor" href="#_3-ucd-ning-biznesdagi-statistik-afzalliklari" aria-label="Permalink to &quot;3. UCD ning biznesdagi statistik afzalliklari&quot;">​</a></h3><ul><li>Tadqiqotlarga ko&#39;ra, IT startaplarning **17%**i foydalanuvchiga yo&#39;naltirilgan dizayn tamoyillarini joriy qilmagani sababli muvaffaqiyatsizlikka uchraydi (bozorga keraksiz mahsulot ishlab chiqaradi).</li><li>Boshqa tadqiqotlar shuni ko&#39;rsatadiki, UCD biznes egalari erishadigan muvaffaqiyatning **taxminan 30%**ini tashkil etadi.</li><li>UCD ishlab chiqish jarayonida xatolarni erta aniqlab, qayta dasturlash (re-work) xarajatlarini 50% ga qisqartiradi.</li></ul><h3 id="_4-ucd-ning-4-bosqichli-iterativ-sikli-iso-9241-210" tabindex="-1">4. UCD ning 4 bosqichli iterativ sikli (ISO 9241-210) <a class="header-anchor" href="#_4-ucd-ning-4-bosqichli-iterativ-sikli-iso-9241-210" aria-label="Permalink to &quot;4. UCD ning 4 bosqichli iterativ sikli (ISO 9241-210)&quot;">​</a></h3><p>UCD bir martalik chiziqli jarayon emas, balki doimiy aylanma (iterativ) sikldir:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>[1. Foydalanish kontekstini aniqlash] </span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>[2. Talablarni aniqlash (Foydalanuvchi &amp; Biznes)]</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>[3. Loyihaviy yechimlarni yaratish (Prototiplash)]</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>[4. Dizaynni baholash (Haqiqiy foydalanuvchilar bilan)]</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 └───► Agar talab bajarilmasa, 1 yoki 2-bosqichga qaytish!</span></span></code></pre></div><hr>`,14))]),i("div",f,[i("h2",z,[t(n,{name:"file-text"}),a[18]||(a[18]=l(" Amaliy mashg'ulot va topshiriqlar ",-1)),a[19]||(a[19]=i("a",{class:"header-anchor",href:"#amaliy-mashg-ulot-va-topshiriqlar","aria-label":`Permalink to "<Icon name="file-text" /> Amaliy mashg'ulot va topshiriqlar"`},"​",-1))]),a[20]||(a[20]=o('<h3 id="_1-topshiriq-tizim-xatolik-matnlarini-ucd-tamoyili-bo-yicha-qayta-yozish-oson" tabindex="-1">1-topshiriq. Tizim xatolik matnlarini UCD tamoyili bo&#39;yicha qayta yozish (oson) <a class="header-anchor" href="#_1-topshiriq-tizim-xatolik-matnlarini-ucd-tamoyili-bo-yicha-qayta-yozish-oson" aria-label="Permalink to &quot;1-topshiriq. Tizim xatolik matnlarini UCD tamoyili bo&#39;yicha qayta yozish (oson)&quot;">​</a></h3><p>Quyida berilgan 3 ta texnik xatolik matnini UCD ning &quot;Tushunarli til&quot; va &quot;Xatolarni tuzatish yechimini ko&#39;rsatish&quot; tamoyillari asosida foydalanuvchiga samimiy va yordam beruvchi qilib qayta yozing:</p><ol><li><code>Error 500: Database connection timeout.</code></li><li><code>Invalid input: Password must contain min 8 chars, 1 digit, 1 special.</code></li><li><code>Transaction failed: Code 0x88F2.</code></li></ol><p><strong>Yechim:</strong></p><ol><li><code>Server bilan vaqtincha aloqa uzildi. Iltimos, bir daqiqadan so&#39;ng sahifani yangilang yoki qayta urinib ko&#39;ring.</code></li><li><code>Parol kamida 8 ta belgidan iborat bo&#39;lishi va kamida 1 ta raqam hamda 1 ta maxsus belgi (!@#$) qatnashishi kerak.</code></li><li><code>To&#39;lov amalga oshmadi. Kartangizda yetarli mablag&#39; borligini yoki to&#39;lov limitini tekshirib ko&#39;ring.</code></li></ol><h3 id="_2-topshiriq-mobil-bank-ilovasi-uchun-ucd-auditi-o-rta" tabindex="-1">2-topshiriq. Mobil bank ilovasi uchun UCD auditi (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-mobil-bank-ilovasi-uchun-ucd-auditi-o-rta" aria-label="Permalink to &quot;2-topshiriq. Mobil bank ilovasi uchun UCD auditi (o&#39;rta)&quot;">​</a></h3><p>Foydalanuvchi mobil ilova orqali kommunal to&#39;lov qilmoqchi, biroq kvitansiya raqamini xato kiritganda dastur to&#39;satdan yopilib qolmoqda yoki butun formani tozalab tashlamoqda. Ushbu muammoni UCD ning &quot;Xatolarning oldini olish&quot;, &quot;Feedback&quot; va &quot;Foydalanuvchi kuch sarfini kamaytirish&quot; tamoyillari bo&#39;yicha tahlil qiling va 3 ta aniq yechim bering.</p><p><strong>Yechim:</strong></p><ol><li><strong>Xatolarning oldini olish (Error Prevention):</strong> Kvitansiya raqami kiritilayotgan maydonga faqat raqamli klaviatura (numeric keyboard) ochilishi va raqamlar soni belgilangan formatda (masalan, 12 ta raqam) cheklanishi kerak.</li><li><strong>Feedback (Qayta aloqa):</strong> Raqam noto&#39;g&#39;ri kiritilsa, butun ilovani yopmasdan, maydon ostida qizil yozuvda &quot;Kvitansiya raqami 12 ta raqamdan iborat bo&#39;lishi kerak&quot; degan aniq xabar chiqishi kerak.</li><li><strong>Kuch sarfini kamaytirish (Minimize effort):</strong> Foydalanuvchi xato qilganida avval to&#39;ldirilgan boshqa maydonlar (F.I.SH., manzil) o&#39;chib ketmasligi, faqat xato maydon qayta kiritilishi shart.</li></ol><h3 id="_3-topshiriq-4-bosqichli-ucd-siklini-maktab-kutubxonasi-elektron-tizimiga-qo-llash-qiyin" tabindex="-1">3-topshiriq. 4 bosqichli UCD siklini maktab kutubxonasi elektron tizimiga qo&#39;llash (qiyin) <a class="header-anchor" href="#_3-topshiriq-4-bosqichli-ucd-siklini-maktab-kutubxonasi-elektron-tizimiga-qo-llash-qiyin" aria-label="Permalink to &quot;3-topshiriq. 4 bosqichli UCD siklini maktab kutubxonasi elektron tizimiga qo&#39;llash (qiyin)&quot;">​</a></h3><p>Maktab kutubxonasida kitoblarni qidirish va ijaraga olish uchun elektron ilova yaratilmoqda. UCD ning 4 ta asosiy bosqichini ushbu loyiha uchun to&#39;liq yoritib bering.</p><p><strong>Yechim:</strong></p><ol><li><strong>Foydalanish kontekstini aniqlash:</strong><ul><li>Foydalanuvchilar: 5–11 sinf o&#39;quvchilari va kutubxonachi;</li><li>Muhit: Ko&#39;pincha maktab tanaffusidagi 5–10 daqiqalik qisqa vaqtda, smartfon yoki kutubxonadagi planshet orqali kitob qidirish.</li></ul></li><li><strong>Talablarni aniqlash:</strong><ul><li>O&#39;quvchi: Kitob nomini yoki muallifini 1 qadamda qidirish, kitob fondda bor yoki yo&#39;qligini darhol bilish;</li><li>Kutubxonachi: Kitob berilgan sana va qaytarish muddatini avtomatik qayd etish.</li></ul></li><li><strong>Loyihaviy yechimlarni yaratish:</strong><ul><li>Qog&#39;ozda tezkor eskiz (sketch) chizish;</li><li>Figmada oddiy wireframe (qidiruv maydoni, natijalar ro&#39;yxati va &quot;Band qilish&quot; tugmasi);</li><li>Bosiladigan klik prototip yaratish.</li></ul></li><li><strong>Dizaynni baholash:</strong><ul><li>5 nafar o&#39;quvchiga prototipni berib, &quot;Fizika 10-sinf darsligini topib, band qiling&quot; vazifasini topshirish;</li><li>O&#39;quvchilar qayerda tutilib qolganini kuzatish va qayta dizaynga o&#39;zgartirish kiritish.</li></ul></li></ol><hr>',14))]),i("div",x,[i("h2",D,[t(n,{name:"file-text"}),a[21]||(a[21]=l(" Tezkor nazorat savollari ",-1)),a[22]||(a[22]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[23]||(a[23]=o("<ol><li>Donald Norman kim va u UX sohasiga qanday hissa qo&#39;shgan? <ul><li><em>Javob:</em> 1993-yilda Apple kompaniyasida ishlagan holda birinchi bo&#39;lib &quot;User Experience&quot; iborasini rasmiy lavozim sifatida kiritgan olim va dizayner.</li></ul></li><li>UCD nima uchun bir martalik chiziqli jarayon emas, balki iterativ jarayon hisoblanadi? <ul><li><em>Javob:</em> Chunki testlash bosqichida foydalanuvchilar qiyinchilikka uchrasa, dizayn qayta ko&#39;rib chiqiladi va yangilanadi; mahsulot mukammallashguncha sikl takrorlanadi.</li></ul></li><li>Startaplarning qancha foizi UCD tamoyillariga amal qilmagani tufayli muvaffaqiyatsizlikka uchraydi? <ul><li><em>Javob:</em> 17% startaplar (foydalanuvchiga keraksiz mahsulot ishlab chiqargani sababli).</li></ul></li><li>Feedback (qayta aloqa) tamoyili nima uchun interfeysda o&#39;ta muhim? <ul><li><em>Javob:</em> U foydalanuvchiga tizim uning amalini qabul qilganini (masalan, yuklanayotganini yoki to&#39;lov o&#39;tganini) bildiradi va noaniqlik hamda xavotirni yo&#39;qotadi.</li></ul></li></ol><hr>",2))]),i("div",C,[i("h2",U,[t(n,{name:"file-text"}),a[24]||(a[24]=l(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[25]||(a[25]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[26]||(a[26]=i("ul",null,[i("li",null,[i("strong",null,`"Men foydalanuvchiman, demak boshqalar ham men kabi o'ylaydi" degan xato (False-Consensus Effect):`),l(" Dizayner o'z didiga qarab qaror qabul qilmasligi kerak. Haqiqiy foydalanuvchilar mutlaqo boshqacha yosh, bilim va ko'nikmaga ega bo'lishi mumkin.")]),i("li",null,[i("strong",null,"Baholash bosqichini o'tkazib yuborish:"),l(" Faqat dizayn chizib, dasturchiga topshirish va uni haqiqiy odamlarda sinab ko'rmaslik eng xavfli xatodir. Testlash har doim dasturlashdan oldin boshlanishi zarur.")])],-1))])])}const S=s(h,[["render",_]]);export{K as __pageData,S as default};
